import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import puppeteer from 'puppeteer-core';
import { createViewMap, readInterleaveConfig } from '../src/fx/interleave.ts';

const config = readInterleaveConfig(new URLSearchParams());
// SHA-256 of RGBA view indices (bottom row first), generated by the supplied
// interleaveV2.py view_idx function, with val_x=10.0298, val_tan=0.27781
// (user calibration, 2026-10-29), and w changed for each test size.
for (const [w, h, hash] of [
  [240, 150, 'd5a23d84019832b420c47ef3b2329433bad687aa03ace6b16aab73570ad5d0a4'],
  [1920, 1200, '627db6dc8dc9658ccff916e4daf1ef715e04ef5e85faaa67cf273a56ba2d8952'],
  [333, 187, 'ab87b10be754f394f63d5afc367ffa5e587f9c3913d01d5f377da6061fcfd0fb'],
]) assert.equal(createHash('sha256').update(createViewMap(w, h, config)).digest('hex'), hash, `Python parity ${w}x${h}`);
assert.deepEqual(readInterleaveConfig(new URLSearchParams('pitch=0&slant=NaN&views=Infinity&offset=&viewScale=-1&focus=0&viewSpan=-2')), config);
console.log('PASS Python reference parity (3 sizes) and invalid calibration fallback');

const port = process.env.PORT;
assert.ok(port, 'Set PORT explicitly to the high-slide dev server');
mkdirSync('tools/shots', { recursive: true });
const browser = await puppeteer.launch({
  executablePath: process.env.CHROME ?? 'C:/Program Files/Google/Chrome/Application/chrome.exe',
  headless: true,
  args: ['--ignore-gpu-blocklist', '--enable-gpu', '--use-angle=d3d11'],
  defaultViewport: { width: 1920, height: 1200 },
});
try {
  const page = await browser.newPage(), errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto(`http://127.0.0.1:${port}/?debug`);
  assert.match(await page.title(), /MEGALODON DROP/);
  await page.waitForFunction(() => window.__game, { timeout: 120000 });
  await page.evaluate(() => window.__game.renderer.setAnimationLoop(null));
  const mapping = await page.evaluate(async () => {
    const THREE = await import('/node_modules/three/build/three.module.js');
    const { Interleave, readInterleaveConfig, createViewMap } = await import('/src/fx/interleave.ts');
    const renderer = new THREE.WebGLRenderer();
    renderer.setPixelRatio(2);
    renderer.setSize(120, 75);
    const cfg = { ...readInterleaveConfig(new URLSearchParams()), scale: 1 };
    const pass = new Interleave(renderer, cfg);
    pass.setSize(240, 150);
    const textureData = Array.from({ length: cfg.views }, (_, view) => {
      const data = new Uint8Array(240 * 150 * 4);
      for (let y = 0; y < 150; y++) for (let x = 0; x < 240; x++) {
        const p = (y * 240 + x) * 4;
        data.set([view * 7 + x % 7, view * 5 + y % 5, view * 3 + (x + y) % 3, 255], p);
      }
      return data;
    });
    const textures = textureData.map(data => {
      const texture = new THREE.DataTexture(data, 240, 150);
      texture.needsUpdate = true;
      return texture;
    });
    const target = new THREE.WebGLRenderTarget(240, 150);
    renderer.setRenderTarget(target);
    const base = new THREE.PerspectiveCamera(74, 240 / 150, 0.12, 60000);
    base.position.set(2, 3, 4); base.rotation.set(0.2, 0.5, 0.1); base.updateMatrixWorld();
    const original = base.matrixWorld.toArray(), offsets = [], convergence = [];
    const focal = new THREE.Vector3(0, 0, -cfg.focus).applyMatrix4(base.matrixWorld);
    let index = 0;
    pass.render(base, camera => {
      offsets.push(camera.position.distanceTo(base.position));
      convergence.push(focal.clone().project(camera).x);
      return textures[index++];
    });
    const pixels = new Uint8Array(240 * 150 * 4);
    renderer.readRenderTargetPixels(target, 0, 0, 240, 150, pixels);
    const ids = createViewMap(240, 150, cfg);
    let mismatch = 0;
    for (let p = 0; p < pixels.length; p += 4) for (let c = 0; c < 3; c++) {
      if (pixels[p + c] !== textureData[ids[p + c]][p + c]) mismatch++;
    }
    const restored = JSON.stringify(original) === JSON.stringify(base.matrixWorld.toArray());
    const mapBefore = pass.map;
    pass.updateConfig({ ...cfg, reverse: true, span: 0.1, focus: 12 });
    let previewCalls = 0, signedShift = 0;
    pass.render(base, camera => {
      previewCalls++;
      signedShift = camera.position.clone().sub(base.position).dot(new THREE.Vector3().setFromMatrixColumn(base.matrixWorld, 0));
      return textures[0];
    }, 0);
    renderer.readRenderTargetPixels(target, 0, 0, 240, 150, pixels);
    let previewMismatch = 0;
    for (let p = 0; p < pixels.length; p += 4) for (let c = 0; c < 3; c++) {
      if (pixels[p + c] !== textureData[0][p + c]) previewMismatch++;
    }
    const cameraMapReused = pass.map === mapBefore;
    const newConfig = { ...cfg, pitch: 9.8, slant: -0.2, offset: 3 };
    pass.updateConfig(newConfig);
    let nextView = 0;
    pass.render(base, () => textures[nextView++]);
    renderer.readRenderTargetPixels(target, 0, 0, 240, 150, pixels);
    const newIds = createViewMap(240, 150, newConfig);
    let updatedMismatch = 0;
    for (let p = 0; p < pixels.length; p += 4) for (let c = 0; c < 3; c++) {
      if (pixels[p + c] !== textureData[newIds[p + c]][p + c]) updatedMismatch++;
    }
    const result = { mismatch, views: index, restored, maxConvergenceError: Math.max(...convergence.map(Math.abs)), span: offsets[0] + offsets.at(-1),
      previewMismatch, previewCalls, signedShift, cameraMapReused, updatedMismatch, calibrationMapRebuilt: pass.map !== mapBefore };
    textures.forEach(t => t.dispose()); target.dispose(); pass.dispose(); renderer.dispose();
    return result;
  });
  assert.equal(mapping.mismatch, 0, 'GPU RGB, row orientation, view order and atlas boundaries');
  assert.equal(mapping.views, 24); assert.equal(mapping.restored, true);
  assert.ok(mapping.maxConvergenceError < 1e-6); assert.ok(Math.abs(mapping.span - 0.065) < 1e-6);
  assert.equal(mapping.previewMismatch, 0); assert.equal(mapping.previewCalls, 1);
  assert.ok(Math.abs(mapping.signedShift - 0.05) < 1e-6, 'reverse order changes camera direction');
  assert.equal(mapping.cameraMapReused, true); assert.equal(mapping.updatedMismatch, 0); assert.equal(mapping.calibrationMapRebuilt, true);
  console.log('PASS GPU mapping and off-axis cameras', mapping);

  await page.focus('#btn-start');
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(() => document.activeElement.hasAttribute('data-interleave-toggle')), true, 'toggle reachable inside dialog');
  await page.keyboard.press('Space');
  assert.equal(await page.$eval('#interleave-toggle', el => el.getAttribute('aria-pressed')), 'true');
  await page.click('#language-toggle');
  assert.equal(await page.$eval('#interleave-toggle', el => el.textContent), '3D 交织');
  await page.click('#language-toggle');
  const stats = await page.evaluate(async () => {
    const g = window.__game;
    g.hud.hideScreen(); g.hud.showHud(true); g.phase = 'ride';
    g.present(1 / 60);
    const renderer = g.renderer, gl = renderer.getContext();
    const debug = gl.getExtension('WEBGL_debug_renderer_info');
    const result = { gpu: debug ? gl.getParameter(debug.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER), width: renderer.domElement.width, height: renderer.domElement.height, modes: {} };
    for (const enabled of [false, true]) {
      g.fx.setInterleaved(enabled); g.resize();
      for (let i = 0; i < 3; i++) { g.fx.render(g.time); gl.finish(); }
      const times = [];
      renderer.info.autoReset = false;
      for (let i = 0; i < 12; i++) {
        renderer.info.reset();
        const start = performance.now();
        g.fx.render(g.time); gl.finish();
        times.push(performance.now() - start);
      }
      times.sort((a, b) => a - b);
      result.modes[enabled ? 'interleave' : 'normal'] = { medianMs: times[6], p95Ms: times[11], calls: renderer.info.render.calls, triangles: renderer.info.render.triangles, textures: renderer.info.memory.textures };
      renderer.info.autoReset = true;
      const frameTimes = [];
      let previous = await new Promise(resolve => requestAnimationFrame(resolve));
      for (let i = 0; i < 90; i++) {
        g.present(1 / 60);
        const now = await new Promise(resolve => requestAnimationFrame(resolve));
        if (i >= 10) frameTimes.push(now - previous);
        previous = now;
      }
      frameTimes.sort((a, b) => a - b);
      result.modes[enabled ? 'interleave' : 'normal'].rafMedianMs = frameTimes[40];
      result.modes[enabled ? 'interleave' : 'normal'].rafP95Ms = frameTimes[76];
    }
    return result;
  });
  console.log('MEASURE fixed view synchronous CPU+GPU render latency; not gameplay FPS', JSON.stringify(stats));
  writeFileSync('tools/shots/interleave-performance.json', JSON.stringify(stats, null, 2));
  await page.screenshot({ path: 'tools/shots/interleave-start.png' });
  for (const height of [162, 820, 1620]) {
    await page.evaluate(height => {
      const g = window.__game;
      let best = { delta: Infinity, seg: 0, s: 0 };
      for (const seg of g.track.segments) for (let i = 0; i < seg.count; i++) {
        const delta = Math.abs(seg.pos[i * 3 + 1] - height);
        if (delta < best.delta) best = { delta, seg: seg.index, s: i };
      }
      g.rider.place(best.seg, best.s, 195 / 3.6); g.rig.reset();
      g.fx.setInterleaved(false); g.resize();
      for (let i = 0; i < 90; i++) g.present(1 / 60);
      g.fx.setInterleaved(true); g.resize(); g.fx.render(g.time);
    }, height);
    await page.screenshot({ path: `tools/shots/interleave-${height}.png` });
  }
  await page.setViewport({ width: 600, height: 400, deviceScaleFactor: 2 });
  await page.evaluate(() => { window.__game.resize(); window.__game.fx.render(0); });
  const resized = await page.evaluate(() => ({ width: window.__game.renderer.domElement.width, height: window.__game.renderer.domElement.height }));
  assert.deepEqual(resized, { width: 1200, height: 800 }, 'native DPR in interleave mode');
  await page.click('#interleave-toggle');
  assert.equal(await page.$eval('#interleave-toggle', el => el.getAttribute('aria-pressed')), 'false');
  assert.equal(await page.evaluate(() => window.__game.renderer.domElement.width), 900, 'normal DPR cap restored');
  await page.goto(`http://127.0.0.1:${port}/?debug&interleave&viewScale=0.125`);
  await page.waitForFunction(() => window.__game, { timeout: 120000 });
  await page.evaluate(() => window.__game.renderer.setAnimationLoop(null));
  assert.equal(await page.$eval('#interleave-toggle', el => el.getAttribute('aria-pressed')), 'true', 'URL starts in interleave mode');
  assert.deepEqual(errors, []);
  console.log('PASS UI toggle, resize / DPR, screenshots, and no browser errors');
} finally { await browser.close(); }
